code.cpp:
#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    string s;
    cin >> s;

    int depth = 0, best = 0;
    for (char ch : s) {
        if (ch == '(') {
            depth++;
            best = max(best, depth);
        } else if (ch == ')') {
            depth--;
        }
    }
    cout << best << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        int depth = 0, best = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                depth++;
                best = Math.max(best, depth);
            } else if (ch == ')') {
                depth--;
            }
        }
        System.out.println(best);
    }
}
